     *
     * # Errors
     * [`RappBindingError`] on invalid input or the wrong protocol phase.
     */
    func cardCompletionAmbiguous(operationId: Data) throws  -> RappBridgeAction
    
    /**
     * Cancel the operation after the card left before transmission provably
     * began.
     *
     * # Errors
     * [`RappBindingError`] on invalid input or the wrong protocol phase.
     */
