public struct FfiConverterTypeRappOperationBridge: FfiConverter {
    typealias FfiType = UInt64
    typealias SwiftType = RappOperationBridge

    public static func lift(_ handle: UInt64) throws -> RappOperationBridge {
        return RappOperationBridge(unsafeFromHandle: handle)
    }

    public static func lower(_ value: RappOperationBridge) -> UInt64 {
        return value.uniffiCloneHandle()
    }

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> RappOperationBridge {
        let handle: UInt64 = try readInt(&buf)
        return try lift(handle)
    }

    public static func write(_ value: RappOperationBridge, into buf: inout [UInt8]) {
        writeInt(&buf, lower(value))
    }
}


#if swift(>=5.8)
