    typealias SwiftType = RappBridgeActionKind

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> RappBridgeActionKind {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .sendFrame
        
        case 2: return .inspectPrerequisites
        
        case 3: return .awaitUserApproval
        
        case 4: return .executeSafeRead
        
        case 5: return .executeCardCommand
        
        case 6: return .resultAcknowledgment
        
        case 7: return .completed
        
        case 8: return .terminal
        
        case 9: return .cancelled
        
        case 10: return .advisoryCancellation
        
        case 11: return .resultAcknowledged
        
        case 12: return .peerReserved
        
        case 13: return .peerUnknownOperation
        
        case 14: return .ignoredDuplicate
        
        case 15: return .noAction
        
        case 16: return .sessionClosed
        
        case 17: return .pairEnded
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: RappBridgeActionKind, into buf: inout [UInt8]) {
        switch value {
        
        
        case .sendFrame:
            writeInt(&buf, Int32(1))
        
        
        case .inspectPrerequisites:
            writeInt(&buf, Int32(2))
        
        
        case .awaitUserApproval:
            writeInt(&buf, Int32(3))
        
        
        case .executeSafeRead:
            writeInt(&buf, Int32(4))
        
        
        case .executeCardCommand:
            writeInt(&buf, Int32(5))
        
        
        case .resultAcknowledgment:
            writeInt(&buf, Int32(6))
        
        
        case .completed:
            writeInt(&buf, Int32(7))
        
        
        case .terminal:
            writeInt(&buf, Int32(8))
        
        
        case .cancelled:
            writeInt(&buf, Int32(9))
        
        
        case .advisoryCancellation:
            writeInt(&buf, Int32(10))
        
        
        case .resultAcknowledged:
            writeInt(&buf, Int32(11))
        
        
        case .peerReserved:
            writeInt(&buf, Int32(12))
        
        
        case .peerUnknownOperation:
            writeInt(&buf, Int32(13))
        
        
        case .ignoredDuplicate:
            writeInt(&buf, Int32(14))
        
        
        case .noAction:
            writeInt(&buf, Int32(15))
        
        
        case .sessionClosed:
            writeInt(&buf, Int32(16))
        
        
